<script setup lang="ts">import type{Job}from'@career-launch/shared';import{EmptyState}from'@career-launch/ui';import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{repository}from'../../services/repository';import JobCard from'../jobs/JobCard.vue';const router=useRouter();const jobs=ref<Job[]>([]);onMounted(async()=>{jobs.value=(await repository.jobs.list({city:[],category:[],education:[],sort:'latest',page:1,pageSize:50})).items.filter(item=>item.favorite)})</script>
<template><section><h1>我的收藏</h1><p class="lead">集中查看你准备进一步了解的职位。</p><EmptyState v-if="!jobs.length" title="还没有收藏职位" description="浏览职位时点击星标，方便之后集中比较。" action-label="去找职位" @action="router.push('/jobs')"/><div v-else class="grid"><JobCard v-for="job in jobs" :key="job.id" :job="job"/></div></section></template><style scoped>h1{margin:0;font-size:30px}.lead{color:var(--cl-muted)}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style>
